var RockCommerce={cid:0,components:{},addComponent(c){const cid=++this.cid;this.components[cid]=c;c.$el.setAttribute("rc-cid",cid)},};document.addEventListener("alpine:init",()=>{Alpine.data("rockcommerce",()=>({components:{},hooksAfter:{},hooksBefore:{},init(){this.components=RockCommerce.components;RockCommerce=this;document.dispatchEvent(new CustomEvent("rockcommerce:init",{detail:this,}));Object.values(this.components).forEach((component)=>{console.log(component.type,"own?",component.hasOwnProperty("ready"));if(typeof component.ready==="function"){component.ready()}});document.dispatchEvent(new CustomEvent("rockcommerce:ready",{detail:this,}))},after(){console.log("after!")},}))})